# The construction functions use ONLY their constructed child schedules.
# They do not use the uploaded SLM steps.
# The input types must be respected: S takes (s,s), F takes (s,f).
# Their rates follow from the sum identities for these types.

E = Float64[]

function S(a, b)
    alpha = 1 / (1 + sum(a))
    beta  = 1 / (1 + sum(b))
    mu = 1 + 2 / (sqrt(alpha^2 + 6*alpha*beta + beta^2) + alpha + beta)
    return [a; mu; b]
end

function F(a, b)
    alpha = 1 / (1 + sum(a))
    beta  = 1 / (1 + 2*sum(b))
    mu = 1 + 2 / (sqrt(alpha^2 + 8*alpha*beta) + alpha)
    return [a; mu; b]
end

