# Check the original and reconstructed schedules, without reordering.
# This tolerance verifies the quantitative statement proposed for the paper.
tolerance = 2e-4
errors = Dict{Int,Float64}()

for K in 1:50
    if !haskey(compositions, K)
        println("K = $K: no construction stored")
        continue
    end
    @assert length(slm_steps[K]) == length(compositions[K]) == K
    err = maximum(abs.(slm_steps[K] - compositions[K]))
    errors[K] = err
    println("K = $K: max error = $err; within tolerance = $(err <= tolerance)")
end

println("\nVerified constructions: ", count(e -> e <= tolerance, values(errors)), "/50")
println("Largest absolute error: ", maximum(values(errors)))

